    "narration": "Улица Эстеры — одна из самых атмосферных и легендарных улиц краковского Казимежа. Её название отсылает не только к библейской царице Эсфири, но и к Эстерке — легендарной еврейской возлюбленной короля Казимира III Великого. По преданию, именно благодаря влиянию Эстерки при дворе XIV века еврейская община получила защиту и поддержку, а её имя и сегодня живёт в местных преданиях и топонимике.\n\nЕврейское наследие улицы Эстеры глубоко уходит корнями в прошлое. Уже в XVII веке вся земля в этом районе принадлежала евреям, и улица Эстеры стала важной частью повседневной жизни еврейского квартала. По адресу Эстеры, 6 находилась школа Талмуд-Тора — религиозное учебное заведение, которое в межвоенный период посещали до 1500 учеников, а управляли им главы синагог и хасидских молитвенных домов. В подвале исторической каменицы на улице Эстеры сохранились фрагменты оборонительной стены XIV века, напоминающие о том, что Казимеж был отдельным городом и первой линией обороны Кракова.\n\nСегодня улица Эстеры — это оживлённая и атмосферная пешеходная артерия, соединяющая Плац Новы с сердцем Казимежа. Среди них — знаменитое кафе Singer (№20), где можно посидеть за старинными швейными машинками, и Moment Café (№22) с психоделическим интерьером в духе 1960-х и яркой ночной жизнью. Атмосферу улицы дополняют зелёные дворики и исторические детали, делающие её любимым местом встреч как для местных жителей, так и для гостей города.\n\nУлица Эстеры — это не только место для гастрономических и культурных открытий, но и живой памятник стойкости и творчеству еврейской общины Кракова. Прогуливаясь по ней, отдыхая в кафе или просто впитывая атмосферу, вы открываете для себя многослойное наследие Казимежа и его уникальный дух.",
    "teaser": "Наша следующая остановка: Улица Эстеры. Очаровательная улица в самом сердце Казимежа, улица Эстеры богата еврейской историей и легендами, названа как в честь библейской Эсфири, так и Эстерки — легендарной еврейской возлюбленной короля Казимира Великого.",
