    "narration": "На улице Йозефа, 42 в Казимежe находится один из самых значимых и известных следов мезузы в Кракове. Мезуза — это небольшой футляр, который традиционно крепится на правом косяке двери еврейских домов и учреждений и содержит рукописный пергамент с отрывками из книги Второзакония. Её присутствие отмечает дом как еврейский и служит ежедневным напоминанием о вере и традиции.\n\nДо Второй мировой войны в Кракове процветала еврейская община, и мезузы можно было встретить на тысячах дверей. Сегодня большинство оригинальных мезуз исчезли, но диагональные следы или вмятины на косяках — как на Йозефа, 42 — молча свидетельствуют о жизнях, прерванных и разрушенных во время Холокоста. След мезузы по этому адресу особенно знаменит и стал обязательным пунктом для всех, кто интересуется еврейским наследием Казимежа.\n\nВ этом здании когда-то располагалось общество «Ковеа Иттим ле-Тора» — ортодоксальный молитвенный дом, основанный в 1810 году и отреставрированный в 1912-м. Общество организовывало уроки Талмуда для взрослых членов еврейской общины, а на фасаде до сих пор можно увидеть надпись на иврите «Хевра Кедоша Ковеа Иттим ле-Тора». Перед войной обществом управляли Вольф Браус и Якуб Ханбиум. Во время нацистской оккупации здание было разрушено, а после войны временно использовалось как приют для переселенцев.\n\nСегодня след мезузы на Йозефа, 42 — не только исторический артефакт, но и символ стойкости и памяти. Современные художники даже отлили бронзовые мезузы по этим следам, чтобы память и смысл мезузы продолжали жить для новых поколений. Прогуливаясь по Казимежу, обращайте внимание на такие едва заметные отметины на дверных косяках — это последние материальные напоминания о некогда процветающем еврейском мире Кракова.",
    "teaser": "Наша следующая остановка: Дом с мезузой (Молитвенный дом «Ковеа Иттим ле-Тора»). Самый известный след мезузы в Кракове, сохранившийся у входа в бывший молитвенный дом «Ковеа Иттим ле-Тора», — это трогательное напоминание о еврейских семьях и традициях, некогда процветавших в Казимежe.",
