    "narration": "Добро пожаловать в Старую синагогу — старейшее синагогальное здание, сохранившееся в Польше, и одну из самых ценных жемчужин еврейской архитектуры Европы. Она расположена по адресу Широкая, 24, в районе Казимеж, и была построена в XV веке: по разным оценкам, завершение строительства датируется периодом с 1407 по 1492 годы. Современный облик синагога приобрела после масштабной реконструкции 1570 года, проведённой итальянским архитектором Маттео Гуччи, который сохранил готическое ядро, добавив ренессансные элементы — высокий парапет, тосканские колонны и окна, расположенные высоко над землёй, вдохновлённые военной архитектурой для защиты от осады.\n\nНа протяжении веков Старая синагога была главным религиозным, социальным и организационным центром еврейской общины Кракова. Она относилась к ортодоксальному иудаизму и следовала ашкеназскому обряду. После военных разрушений большой молитвенный зал сохраняет восстановленный готико-ренессансный характер: крестовые своды, ренессансную биму с кованой балюстрадой и каменный ковчег Торы (Арон Кодеш) на восточной стене. Женское отделение (эзрат нашим) появилось в XVII веке, а в начале XX века были проведены дальнейшие расширения и реставрации.\n\nСтарая синагога сыграла заметную роль и в истории Польши. В 1794 году здесь выступал генерал Тадеуш Костюшко, призывая еврейскую общину поддержать восстание — этому событию посвящена памятная табличка в вестибюле. Здание пережило пожары, войны и разграбления, но самые тяжёлые разрушения пришлись на время Второй мировой войны: нацисты осквернили синагогу, разграбили её и использовали как склад. В 1943 году во дворе синагоги были расстреляны 30 польских заложников.\n\nПосле войны синагога была тщательно восстановлена (1956–1959) и в 1959 году передана Историческому музею Кракова, нынешнему Музею Кракова. Сегодня здесь проходят экспозиции, посвящённые религиозной и повседневной жизни краковских евреев: рождение, брак, ритуалы, праздники и традиции. В женском зале часто проходят временные выставки, а в главном зале представлены предметы и обычаи, связанные с важнейшими еврейскими праздниками и обрядами.\n\nАрхитектура и история Старой синагоги вдохновляли художников, писателей и кинематографистов — она появляется, например, в фильме Стивена Спилберга «Список Шиндлера». Несмотря на века потрясений, Старая синагога остаётся мощным символом памяти и стойкости — местом, где можно задуматься о наследии еврейской жизни Кракова и отдать дань уважения ушедшим поколениям.",
    "teaser": "Наша следующая остановка: Старая синагога. Самая старая сохранившаяся синагога в Польше, Старая синагога — это крепостное здание в готическом и ренессансном стилях в самом сердце Казимежа, где сегодня размещается музей еврейской истории и культуры.",
