    "narration": "Синагога Вольфа Поппера, также известная как синагога Поппера или Бочьяна, находится по адресу Широкая, 16 в самом сердце Казимежа. Она была основана в 1620 году Вольфом Поппером — одним из самых богатых еврейских торговцев и банкиров Кракова. В своё время синагога считалась одной из самых роскошных в городе, славилась богатым убранством и впечатляющей барочной архитектурой. Поппер, прозванный «Аист» за свою привычку задумчиво стоять на одной ноге, сколотил состояние на международной торговле тканями и селитрой, став одним из самых состоятельных людей Европы.\n\nЗдание синагоги выполнено из кирпича и камня, его прямоугольный объём поддерживают массивные контрфорсы, а главный молельный зал перекрыт цилиндрическим сводом и доступен через небольшой вестибюль. Двор синагоги, ограждённый высокой оштукатуренной стеной с тремя воротами, ведёт на улицу Широкая. Над центральными воротами размещена табличка с надписью на иврите, посвящённой основателю и реставрации здания в 1904 году. Оригинальные двери были украшены изображениями четырёх животных — орла, леопарда, льва и оленя, символизирующих добродетели праведного человека.\n\nНесмотря на былое великолепие, дорогостоящее содержание синагоги разорило наследников Поппера, и к середине XVII века она перешла в собственность еврейской общины Казимежа. За столетия здание неоднократно перестраивалось, в XIX веке появились женские галереи и пристройки. Стены и свод были когда-то богато расписаны, но сегодня покрыты белой краской.\n\nК сожалению, во время Второй мировой войны интерьер синагоги был полностью уничтожен нацистами, и после войны она перестала выполнять религиозные функции. В 1965 году здание было передано Старомейскому молодёжному культурному центру (YCC), который переоборудовал его под художественные и образовательные мероприятия. Сегодня бывшая женская галерея служит художественной мастерской и книжным магазином, а здание стало живым культурным центром, где проходят выставки, мастер-классы и мероприятия, посвящённые еврейской истории и искусству.\n\nСинагогу Вольфа Поппера легко не заметить — она спрятана между двумя домами, но её наследие живёт благодаря культурной жизни Казимежа.",
    "teaser": "Наша следующая остановка: Синагога Вольфа Поппера. Основанная в 1620 году одним из самых богатых еврейских купцов Кракова, синагога Вольфа Поппера — барочная жемчужина Казимежа, ныне дом культурного центра и книжного магазина.",
