    "narration": "Добро пожаловать на улицу Широкую — подлинное сердце еврейского Казимежа и одно из самых атмосферных мест Кракова. Несмотря на название, Широкая — это не обычная улица, а широкая вытянутая площадь, которая веками служила центром еврейской жизни города. Изначально это было ядро средневековой деревни Бавул, а после изгнания евреев из Кракова в 1495 году именно здесь они поселились и создали Оппидум Юдаеорум — Еврейский город, отделённый от остального Казимежа собственными стенами.\n\nУже к XVII веку улица Широкая стала оживлённым центром процветающего еврейского квартала. Уникально для Европы, здесь когда-то стояли сразу четыре синагоги. Сегодня Старую синагогу и синагогу Рему (с историческим кладбищем) по-прежнему можно увидеть как яркие символы еврейского наследия, а синагоги Поппера и Высокая напоминают о духовном и культурном богатстве этого места. На улице также находится историческая миква в подвале отеля Klezmer Hois и дом, где родилась основательница косметической империи Хелена Рубинштейн (№14).\n\nПо словам средневекового хрониста Яна Длугоша, здесь могли стоять первые здания университета, основанного Казимиром Великим, хотя никаких следов не сохранилось. В XVI–XVII веках улицу окружали религиозные и буржуазные дома, многие из которых были разрушены во время Второй мировой войны, но затем восстановлены. Сегодня Широкая — это живой центр еврейской культуры, где работают многочисленные рестораны, кафе и культурные заведения.\n\nУлица стала свидетелем трагедий и стойкости. Во время Холокоста еврейское население было выселено, а большая часть трагедий происходила уже за рекой, в гетто Подгуже и лагере Плашув. После войны Широкая постепенно восстанавливалась и с 1990-х годов стала символом еврейского возрождения в Кракове. Ежегодный Фестиваль еврейской культуры, стартовавший в 1988 году, завершается большим концертом под открытым небом именно здесь, собирая тысячи гостей со всего мира.\n\nНа Широкой также находится мемориал жертвам Холокоста и «Лавочка Яна Карского» — бронзовый памятник 2016 года польскому подпольному курьеру, который пытался донести до союзников правду о Холокосте. Скульптуру создал Кароль Бадына; она входит в его международную серию «лавочек Карского». Вашингтонская лавочка в Джорджтаунском университете была более ранним образцом серии, но краковская версия — самостоятельная работа, созданная специально для места у синагоги Рему и старого еврейского кладбища.",
