    "narration": "Кладбище Рему, также известное как Старое еврейское кладбище Кракова, — одно из древнейших и самых значимых еврейских кладбищ Польши. Оно было основано между 1535 и 1551 годами по адресу Широкая, 40, прямо рядом с синагогой Рему в районе Казимеж. Название кладбища связано с раввином Моше Иссерлесом — Рему, чья могила является самым почитаемым местом на кладбище и объектом паломничества евреев со всего мира.\n\nНа протяжении трёх столетий кладбище служило местом захоронения еврейской общины Кракова: здесь хоронили с середины XVI века до его закрытия в 1800 году по распоряжению австрийских властей, запретивших кладбища в густонаселённых районах города. На кладбище Рему покоятся многие выдающиеся личности, включая самого раввина Моше Иссерлеса (Рему, †1572), Мордехая Сабу, Натана Натана Спиру, Йоэля Сиркиса, Исаака Ландау Левиту и Йом-Това Липмана Геллера. Здесь же похоронен и Ицхак Якубович, основатель синагоги Исаака.\n\nВо время Второй мировой войны кладбище было почти полностью разрушено нацистами: стены были снесены, могилы осквернены, а надгробия использовались как строительный материал или продавались. Удивительно, но надгробие раввина Моше Иссерлеса уцелело — некоторые считают это чудом. После войны были проведены масштабные работы по восстановлению: сотни мацев были возвращены, хотя большинство из них уже не стоят на своих исторических местах, а слишком мелкие фрагменты вмурованы в мемориальную стену, которую иногда называют «Краковской стеной плача».\n\nСегодня площадь кладбища составляет около 0,75 гектара, на ней сохранилось более 700 надгробий, самые старые из которых датируются XVI веком. Территория окружена каменной оградой и тщательно поддерживается еврейской общиной Кракова. Посетители часто оставляют квителах — записки с молитвами и просьбами — на могиле Рему, надеясь на его заступничество. Кладбище — это место памяти и размышлений, свидетельство вековой еврейской жизни, учёности и традиций Кракова. Оно напоминает о стойкости общины и о неугасающем почтении к тем, кто формировал её историю.",
    "teaser": "Наша следующая остановка: Кладбище Рему (Старое еврейское кладбище). Одно из старейших сохранившихся еврейских кладбищ Польши, кладбище Рему — это исторический некрополь, основанный в середине XVI века рядом с синагогой Рему, место покоя многих выдающихся раввинов и лидеров еврейской общины Кракова.",
