    "narration": "Улица Варшауэра — одна из ключевых артерий в районе Казимеж в Кракове, проходящая от улицы Эстеры и Плац Новы до улицы Якуба и района кладбища Рему. Эта улица насыщена еврейской историей города и застроена значимыми историческими зданиями и памятниками.\n\nСвоё современное название улица получила в 1908 году в честь Йонатана Варшауэра, еврейского врача и общественного деятеля, связанного с Краковом. До этого она называлась улицей Убогих. До XIX века здесь располагались больница и дом престарелых, что отражает её давнюю роль в системе социальной поддержки общины.\n\nНа улице Варшауэра можно увидеть несколько примечательных зданий: - Варшауэра, 1 (Эстеры, 8): доходный дом начала XX века. - Варшауэра, 2 (Эстеры, 6): дом по проекту Леопольда Тлахны 1909 года, ранее синагога Талмуд-Тора, ныне отель Estera. - Варшауэра, 8 (Мёдова, 27): синагога Купа, построенная около 1635 года, богато украшенный барочный храм, который до сих пор служит центром еврейской культуры и богослужения. - Варшауэра, 9 (Купа, 2): доходный дом по проекту Нахмана Копальда, 1898 год.\n\nРядом с синагогой Купа сохранился фрагмент средневековой оборонительной стены — редкий остаток укреплений, которые когда-то защищали независимый город Казимеж и датируются примерно 1340 годом.\n\nСегодня улица Варшауэра — это оживлённая часть района Казимеж, отражающая как глубокое еврейское наследие, так и современное возрождение. Сочетание исторической архитектуры, культурных памятников и следов средневекового Кракова делает её интересным местом для всех, кто хочет узнать о многослойном прошлом и настоящем города.",
    "teaser": "Наша следующая остановка: Улица Варшауэра. Историческая улица в Казимежe, Краков, соединяющая улицу Эстеры и Плац Новы с улицей Якуба и кладбищем Рему, известна еврейским наследием, историческими зданиями и остатками средневековых укреплений.",
