    "narration": "Еврейский общинный центр Кракова, известный как JCC Krakow, — это динамичный и инклюзивный центр в самом сердце еврейского возрождения Казимежа. Расположенный по адресу Мёдова, 24, сразу за синагогой Темпель, JCC был основан в 2008 году по инициативе принца Уэльского, вдохновлённого встречей с выжившими в Холокосте и осознавшего необходимость создания пространства для вновь формирующейся еврейской общины Кракова.\n\nJCC — это светский культурный и образовательный центр, открытый для евреев и неевреев. Здесь предоставляется широкий спектр социальных, образовательных и благотворительных услуг, и сегодня это главный поставщик еврейских программ в Кракове. В центре действует более 1 100 членов, работает дошкольный центр FRAJDA — первый полноценный плюралистический еврейский детский сад в Кракове со времён Холокоста, а также студенческий клуб при поддержке Hillel International и Bagel Club для молодых семей.\n\nJCC также является главным учреждением, заботящимся почти о 60 выживших в Холокосте в городе, предоставляя транспорт, реабилитацию, питание и досуговые мероприятия. Сильная волонтёрская программа, в которую вовлечены многие нееврейские жители Кракова, помогает организовывать шаббатние ужины, праздники и множество других событий. В JCC проходят занятия по ивриту, арабскому и английскому языкам, йога, книжные клубы, уроки Торы, кулинарные и художественные мастер-классы, кинопоказы и многое другое. Центр также выполняет роль еврейского информационного центра Кракова: Friends of JCC Krakow сообщает о более чем 140 000 посетителей в год, а сам центр остаётся первой точкой контакта для тех, кто хочет узнать о еврейской жизни в городе.\n\nJCC — это и символ, и движущая сила еврейского возрождения в Кракове. Многие молодые члены центра только недавно открыли свои еврейские корни, скрытые их семьями в годы коммунизма. Открытая и дружелюбная атмосфера JCC сделала его центром еврейской жизни города, здесь регулярно проходят концерты, лекции и специальные программы в рамках ежегодного Фестиваля еврейской культуры.\n\nСегодня Еврейский общинный центр Кракова — это свидетельство стойкости, общности и надежды. Это место, где люди разных национальностей могут общаться, учиться и праздновать еврейское наследие, и оно играет ключевую роль в современной истории еврейской жизни в Казимежe и за его пределами.",
    "teaser": "Наша следующая остановка: Еврейский общинный центр Кракова (JCC Krakow). Открытый в 2008 году как современный центр еврейской жизни, культуры и образования, JCC Krakow — это динамичный центр в Казимежe, который поддерживает все поколения, приветствует гостей и играет ключевую роль в еврейском возрождении города.",
