    "narration": "Добро пожаловать на Плац Новы — пульсирующее сердце Казимежа! Вот уже более века эта площадь служит центральным местом встреч для местных жителей. Первоначально она была спроектирована в конце XIX века в рамках модернизации Казимежа и быстро стала центром торговли и общественной жизни, особенно для еврейской общины, когда-то процветавшей здесь.\n\nПлощадь доминирует знаковый круглый рынок — Округляк или Ротонда, построенный в 1900 году как торговый павильон; часть здания позднее приспособили для кошерного забоя птицы, а в 1927 году город сдал его еврейской общине именно для этой цели. С архитектурной точки зрения Ротонда — редкий пример рыночного зодчества начала XX века: кирпичная кладка и характерная круглая форма выделяют ее на фоне окружающих доходных домов, выполненных в стиле конца XIX — начала XX века.\n\nПлац Новы появлялся в литературе и кино, в частности в фильме «Список Шиндлера», где его атмосферные улицы и дворы стали аутентичными декорациями. За годы площадь пережила как шумные рыночные дни, так и военные испытания, а затем — возрождение в посткоммунистическую эпоху.\n\nСегодня площадь знаменита киосками с запеканками — польскими багетами-пиццами, а также оживленными блошиными рынками, которые привлекают как местных жителей, так и туристов. Верите ли вы в эти истории или нет, Плац Новы остается местом, где прошлое встречается с настоящим, а каждый уголок хранит свою историю.\n\nНе забудьте попробовать запеканку — многие считают, что здесь лучшие в Кракове! Площадь также славится ночной жизнью: вокруг нее расположены легендарные бары, такие как Singer и Alchemia, а в течение года здесь проходят разнообразные рынки, ярмарки и фестивали. Несмотря на планы будущей реконструкции, уникальная богемная атмосфера Плац Новы и ощущение общности продолжают определять Казимеж и сегодня.",
