    "narration": "В самом центре Плац Новы возвышается Округляк, или Ротонда — узнаваемый круглый кирпичный павильон, ставший одним из главных символов Казимежа. Построенная в 1900 году, Ротонда изначально служила крытым рынком, а в 1927 году была сдана в аренду еврейской общине и превращена в ритуальную бойню для птицы, обслуживавшую диетические нужды местного еврейского населения. Эта функция сохранялась вплоть до нацистской оккупации во Вторую мировую войну, когда бойня была ликвидирована. После войны Ротонда вновь стала рыночным павильоном, а со временем её роль менялась вместе с самим Казимежем.\n\nС архитектурной точки зрения Ротонда — редкий пример коммерческого зодчества начала XX века в Кракове. Её прочные кирпичные стены и утилитарная круглая форма выделяются на фоне окружающих доходных домов, построенных в основном в конце XIX — начале XX века. За годы Ротонда заняла особое место в сердцах краковян — не только благодаря своей истории, но и роли в повседневной жизни.\n\nСегодня Ротонда известна прежде всего своими киосками с едой, которые опоясывают её по кругу и предлагают легендарные краковские запеканки — открытые багеты с грибами, сыром и множеством начинок. Ротонда также стала сценой культурной жизни: на её крыше иногда проходят концерты Краковского еврейского фестиваля, а в 2008 году здание было внесено в реестр памятников Кракова.\n\nПлощадь вокруг Ротонды всегда полна жизни. С раннего утра здесь работают торговые ряды, где можно купить свежие продукты, антиквариат и многое другое. По субботам сюда съезжаются коллекционеры со всей Польши на знаменитый блошиный рынок, а по воскресеньям проходит оживлённая барахолка одежды. По четвергам здесь даже можно увидеть птичий рынок — традиция, сохранившаяся с дореволюционных времён.\n\nПридёте ли вы сюда за едой, рынками или атмосферой — Ротонда на Плац Новы остаётся живым символом стойкости и креативности Казимежа, местом встречи прошлого и настоящего в самом сердце еврейского Кракова.",
    "teaser": "Наша следующая остановка: Ротонда на Новом Рынке. Знаковая круглая кирпичная ротонда в центре Плац Новы, когда-то ритуальная еврейская бойня, а теперь легендарный центр уличной еды и символ бурлящей жизни Казимежа.",
