    "narration": "Фонд Юдаика — Центр еврейской культуры (Centrum Kultury Żydowskiej) — это краеугольный камень еврейской культурной жизни Кракова, расположенный по адресу Мейсельса, 17 в самом сердце Казимежа. Основанный в 1991 году, Фонд возник как гражданская инициатива в период больших перемен в Польше, при поддержке местных деятелей культуры и покойного президента еврейской общины Чеслава Якубовича. Его миссия — сохранять еврейское наследие, увековечивать память о столетиях еврейской жизни в Польше и создавать живую платформу для польско-еврейского диалога и образования.\n\nЦентр еврейской культуры, управляемый Фондом и открытый в 1993 году, размещается в прекрасно отреставрированном здании бывшего молитвенного дома (Бейт Тефилла), построенного в 1880-х годах и использовавшегося для религиозных целей вплоть до Второй мировой войны. Здание было спасено от разрушения и полностью реконструировано в 1989–1993 годах, а сегодня служит площадкой для лекций, мастер-классов, выставок, концертов, кинопоказов и общественных мероприятий, отражающих еврейскую жизнь прошлого и настоящего. Девиз фонда — «L’dor v’dor» («из поколения в поколение»), подчеркивающий важность передачи еврейской культуры и памяти.\n\nФонд Юдаика особенно известен своей ежегодной флагманской программой Bayit Khaddash («Новый дом») — серией событий от лекций до концертов и спектаклей, проходящих каждую осень с 1996 года. Центр сотрудничает с международными институтами, такими как Итальянский институт культуры, и организует знаковые события, например, ежегодную мемориальную лекцию Александра и Алиции Хец и Settimana della Cultura Ebraica.\n\nПомимо культурных программ, в Центре работает книжный и антикварный магазин в подвале, а на первом этаже — кафе/бар Sara с террасой на крыше и видом на Плац Новы. Деятельность фонда открыта для всех и направлена на популяризацию знаний об истории и культуре евреев среди молодёжи, развитие межкультурного диалога и поддержку ценностей открытого гражданского общества.\n\nСегодня Фонд Юдаика — Центр еврейской культуры — это свидетельство стойкости, творчества и продолжающегося возрождения еврейской жизни в Кракове, обязательное место для всех, кто интересуется мультикультурным наследием города.",
