    "narration": "Добро пожаловать на площадь Вольница — историческое сердце Казимежа и когда-то одну из самых больших рыночных площадей Польши. Когда Казимеж был основан как отдельный город в 1335 году, его рыночная площадь — Рынок Казимежский — была спроектирована так, чтобы соперничать с Главным рынком Кракова и по размеру, и по значимости. Площадь размером 195 на 195 метров стала административным, судебным и торговым центром города. Здесь проходил соляной торговый путь из Велички и Бохни, привлекая купцов и товары со всего региона.\n\nПлощадь была окружена торговыми рядами, суконными лавками и городскими весами, а в центре стояла ратуша, которая сохранилась до наших дней. Мясники, не входившие в цех, могли торговать здесь по субботам благодаря привилегии свободной торговли — forum liberum, что и дало площади название «Вольница» (от польского «wolny» — свободный). Ратуша, изначально готическая с фундаментами XIV века, неоднократно перестраивалась после пожаров, в итоге получив характерный зубчатый парапет и башню. После включения Казимежа в состав Кракова в 1800 году площадь уменьшилась почти вдвое, а ратуша утратила административную функцию. Позже здесь размещались торговая школа и еврейская молодежная школа, а с конца Второй мировой войны — Этнографический музей.\n\nПлощадь Вольница стала свидетелем вековых перемен: от шведских нашествий и городского упадка до современного возрождения. Сегодня здесь проходят фестивали — например, Фестиваль хлеба и Малопольский фестиваль вкуса, а также установлена скульптура-фонтан «Три музыканта» работы Бронислава Хромого в юго-восточном углу. Площадь окружена историческими зданиями, кафе и ресторанами и является приятным местом для прогулки вдали от более туристических районов Кракова.\n\nНа восточной стене ратуши установлена памятная табличка, посвящённая прибытию еврейских беженцев в Польшу во времена короля Казимира Великого — напоминание о многовековой традиции терпимости и многокультурной жизни Казимежа.\n\nПлощадь Вольница — это памятник многослойной истории Казимежа: от средневековой автономии до современного возрождения. Будь то ради архитектуры, фестивалей или просто чашки кофе в исторической обстановке, эта площадь открывает яркое прошлое и настоящее одного из самых интересных район",
    "teaser": "Наша следующая остановка: Рыночная площадь Вольница и Ратуша. Когда-то одна из крупнейших рыночных площадей Польши, площадь Вольница была административным и торговым центром Казимежа, а сегодня здесь находится историческая ратуша и оживлённая культурная жизнь.",
