    "narration": "Бывшая еврейская больница по адресу Скавиньска, 8 — это трогательное напоминание о некогда процветающей еврейской общине Казимежа. Еврейская община перенесла больницу на улицу Скавиньскую в 1820-х годах, а строительство более крупного больничного здания началось здесь в 1860-х. Она стала одним из важнейших еврейских медицинских учреждений Кракова, предоставляя помощь больным, бедным и пожилым, а также служа центром медицинских инноваций и благотворительности.\n\nБольница была построена благодаря усилиям и пожертвованиям местной еврейской общины, что отражало особое значение, придаваемое вопросам здоровья и социальной поддержки. Здесь были современные по тем временам условия, а персонал состоял из еврейских врачей, медсестёр и администраторов. Больница обслуживала всех жителей Казимежа, независимо от вероисповедания, и была символом стремления общины к общественному здравоохранению и взаимопомощи.\n\nВо время нацистской оккупации во Вторую мировую войну больницу вынудили покинуть Казимеж: в октябре 1941 года её перевели на территорию гетто Подгуже, а здание по адресу Скавиньска, 8 немецкие власти превратили в мебельный склад. Документированные страдания, связанные с больницей, продолжились уже в гетто, где учреждение работало до его ликвидации.\n\nПосле войны здание снова стало использоваться медицинскими службами, а сегодня здесь размещаются клинические подразделения Университетской больницы в Кракове. Бывшая еврейская больница признана историческим объектом, а её история является частью более широкой памяти о еврейской жизни, утрате и стойкости в Кракове. Здание остаётся свидетельством заботы и сострадания общины, а также скорбным напоминанием о трагедиях Холокоста.",
    "teaser": "Наша следующая остановка: Бывшая еврейская больница. Развивавшаяся на улице Скавиньской в XIX веке, еврейская больница была важнейшим медицинским и благотворительным учреждением еврейской общины Кракова, принудительно переведённым в гетто Подгуже во время Второй мировой войны.",
